```python
def is_divisible_by_factors(number):
    digits = [int(d) for d in str(number)]
    if len(digits) != len(set(digits)):
        return False
    for digit in digits:
        if digit == 0 or number % digit != 0:
            return False
    return True

def find_least_four_digit_number():
    for num in range(1023, 9999):
        if is_divisible_by_factors(num):
            return num

answer = find_least_four_digit_number()
print(answer)
```
